-- V2.5 expanded candidate quotes; all pending human editorial verification.\n-- Existing 0-41 IDs must not be modified.\nWITH entries AS (SELECT * FROM jsonb_to_recordset($quotes$\n[{"legacy_id":42,"quote_text":"All men by nature desire to know.","author":"Aristotle","theme":"Doubt","source":"Metaphysics I.1 (translation varies)","reflection_prompt":"Which ordinary curiosity has recently surprised you?","review_status":"pending","is_published":false},{"legacy_id":43,"quote_text":"Happiness is an activity of soul in accordance with virtue.","author":"Aristotle","theme":"Meaning","source":"Nicomachean Ethics I.7 (translation varies)","reflection_prompt":"What distinguishes a good life from a pleasant moment?","review_status":"pending","is_published":false},{"legacy_id":44,"quote_text":"Death is nothing to us.","author":"Epicurus","theme":"Mortality","source":"Letter to Menoeceus","reflection_prompt":"What would change if death held less fear?","review_status":"pending","is_published":false},{"legacy_id":45,"quote_text":"By pleasure we mean the absence of pain in the body and of trouble in the soul.","author":"Epicurus","theme":"Meaning","source":"Letter to Menoeceus (translation varies)","reflection_prompt":"Which simple pleasures are enough for you?","review_status":"pending","is_published":false},{"legacy_id":46,"quote_text":"Men are disturbed not by things, but by the views which they take of things.","author":"Epictetus","theme":"Suffering","source":"Enchiridion 5, Higginson translation","reflection_prompt":"How might your judgment shape an uncomfortable event?","review_status":"pending","is_published":false},{"legacy_id":47,"quote_text":"Of things some are in our power, and others are not.","author":"Epictetus","theme":"Freedom","source":"Enchiridion 1, George Long translation","reflection_prompt":"Where are you expending attention without influence?","review_status":"pending","is_published":false},{"legacy_id":48,"quote_text":"Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are.","author":"Epictetus","theme":"Action","source":"Enchiridion 8, George Long translation (excerpt)","reflection_prompt":"Can accepting a circumstance coexist with changing it?","review_status":"pending","is_published":false},{"legacy_id":49,"quote_text":"Life is long if you know how to use it.","author":"Seneca","theme":"Time","source":"On the Shortness of Life (translation varies)","reflection_prompt":"What makes a day feel fully lived?","review_status":"pending","is_published":false},{"legacy_id":50,"quote_text":"While we are postponing, life speeds by.","author":"Seneca","theme":"Time","source":"Moral Letters to Lucilius, Letter 1 (translation varies)","reflection_prompt":"What meaningful thing has been waiting for later?","review_status":"pending","is_published":false},{"legacy_id":51,"quote_text":"Only that day dawns to which we are awake.","author":"Henry David Thoreau","theme":"Time","source":"Walden, Conclusion","reflection_prompt":"What might you notice if you paid closer attention?","review_status":"pending","is_published":false},{"legacy_id":52,"quote_text":"The mass of men lead lives of quiet desperation.","author":"Henry David Thoreau","theme":"Meaning","source":"Walden, Economy","reflection_prompt":"Which forms of striving do we mistake for necessity?","review_status":"pending","is_published":false},{"legacy_id":53,"quote_text":"Simplify, simplify.","author":"Henry David Thoreau","theme":"Action","source":"Walden, Where I Lived, and What I Lived For","reflection_prompt":"What could you remove without losing anything essential?","review_status":"pending","is_published":false},{"legacy_id":54,"quote_text":"Trust thyself: every heart vibrates to that iron string.","author":"Ralph Waldo Emerson","theme":"Freedom","source":"Essays: First Series, Self-Reliance","reflection_prompt":"Where do you borrow confidence from others?","review_status":"pending","is_published":false},{"legacy_id":55,"quote_text":"A foolish consistency is the hobgoblin of little minds.","author":"Ralph Waldo Emerson","theme":"Doubt","source":"Essays: First Series, Self-Reliance","reflection_prompt":"What belief deserves to be revised?","review_status":"pending","is_published":false},{"legacy_id":56,"quote_text":"A wise man proportions his belief to the evidence.","author":"David Hume","theme":"Doubt","source":"An Enquiry Concerning Human Understanding, X","reflection_prompt":"What would change your mind about something important?","review_status":"pending","is_published":false},{"legacy_id":57,"quote_text":"No man's knowledge here can go beyond his experience.","author":"John Locke","theme":"Doubt","source":"An Essay Concerning Human Understanding, IV.iii","reflection_prompt":"Where does your knowledge depend on another person's account?","review_status":"pending","is_published":false},{"legacy_id":58,"quote_text":"To be is to be perceived.","author":"George Berkeley","theme":"Doubt","source":"A Treatise Concerning the Principles of Human Knowledge, §3 (esse est percipi)","reflection_prompt":"What does perception contribute to the world you experience?","review_status":"pending","is_published":false},{"legacy_id":59,"quote_text":"Man is born free, and everywhere he is in chains.","author":"Jean-Jacques Rousseau","theme":"Freedom","source":"The Social Contract I.1 (translation varies)","reflection_prompt":"Which constraints are social rather than natural?","review_status":"pending","is_published":false},{"legacy_id":60,"quote_text":"Over himself, over his own body and mind, the individual is sovereign.","author":"John Stuart Mill","theme":"Freedom","source":"On Liberty, I","reflection_prompt":"Where should another person's authority end?","review_status":"pending","is_published":false},{"legacy_id":61,"quote_text":"All that is solid melts into air.","author":"Karl Marx and Friedrich Engels","theme":"Time","source":"Manifesto of the Communist Party, I (Moore translation)","reflection_prompt":"What changes so rapidly that it feels permanent only for a moment?","review_status":"pending","is_published":false},{"legacy_id":62,"quote_text":"It is not the consciousness of men that determines their existence, but their social existence that determines their consciousness.","author":"Karl Marx","theme":"Meaning","source":"Preface to A Contribution to the Critique of Political Economy, 1859 (translation varies)","reflection_prompt":"How has your social world shaped what seems natural to you?","review_status":"pending","is_published":false},{"legacy_id":63,"quote_text":"The owl of Minerva spreads its wings only with the falling of the dusk.","author":"G. W. F. Hegel","theme":"Time","source":"Elements of the Philosophy of Right, Preface (translation varies)","reflection_prompt":"Can an age only understand itself after it passes?","review_status":"pending","is_published":false},{"legacy_id":64,"quote_text":"Anxiety is the dizziness of freedom.","author":"Søren Kierkegaard","theme":"Freedom","source":"The Concept of Anxiety (translation varies)","reflection_prompt":"What possibility frightens you precisely because you can choose it?","review_status":"pending","is_published":false},{"legacy_id":65,"quote_text":"Existence precedes essence.","author":"Jean-Paul Sartre","theme":"Freedom","source":"Existentialism Is a Humanism","reflection_prompt":"How much of identity is made through what we do?","review_status":"pending","is_published":false},{"legacy_id":66,"quote_text":"One must imagine Sisyphus happy.","author":"Albert Camus","theme":"Meaning","source":"The Myth of Sisyphus (translation varies)","reflection_prompt":"What could make a repetitive life meaningful?","review_status":"pending","is_published":false},{"legacy_id":67,"quote_text":"The limits of my language mean the limits of my world.","author":"Ludwig Wittgenstein","theme":"Doubt","source":"Tractatus Logico-Philosophicus, 5.6","reflection_prompt":"What experience is difficult to put into words?","review_status":"pending","is_published":false},{"legacy_id":68,"quote_text":"What can be shown cannot be said.","author":"Ludwig Wittgenstein","theme":"Doubt","source":"Tractatus Logico-Philosophicus, 4.1212","reflection_prompt":"What can a gesture communicate more directly than speech?","review_status":"pending","is_published":false},{"legacy_id":69,"quote_text":"The world is everything that is the case.","author":"Ludwig Wittgenstein","theme":"Doubt","source":"Tractatus Logico-Philosophicus, 1","reflection_prompt":"Is the world made up of things, or of facts?","review_status":"pending","is_published":false},{"legacy_id":70,"quote_text":"Sapere aude! Have courage to use your own understanding!","author":"Immanuel Kant","theme":"Action","source":"An Answer to the Question: What Is Enlightenment? (translation varies)","reflection_prompt":"Where are you still allowing someone else to think for you?","review_status":"pending","is_published":false},{"legacy_id":71,"quote_text":"Act only according to that maxim whereby you can at the same time will that it should become a universal law.","author":"Immanuel Kant","theme":"Action","source":"Groundwork of the Metaphysics of Morals, II (translation varies)","reflection_prompt":"Would you endorse your own rule if everyone followed it?","review_status":"pending","is_published":false},{"legacy_id":72,"quote_text":"The good life is one inspired by love and guided by knowledge.","author":"Bertrand Russell","theme":"Love","source":"What I Believe","reflection_prompt":"How should care and understanding correct each other?","review_status":"pending","is_published":false},{"legacy_id":73,"quote_text":"One is not born, but rather becomes, a woman.","author":"Simone de Beauvoir","theme":"Freedom","source":"The Second Sex, Introduction to Book II (translation varies)","reflection_prompt":"How do social expectations participate in forming identity?","review_status":"pending","is_published":false},{"legacy_id":74,"quote_text":"Form is emptiness; emptiness is form.","author":"The Heart Sutra","theme":"Doubt","source":"Prajñāpāramitāhṛdaya Sūtra (translation varies)","reflection_prompt":"What changes when things have no independent fixed essence?","review_status":"pending","is_published":false},{"legacy_id":75,"quote_text":"Hatred is never appeased by hatred in this world.","author":"The Dhammapada","theme":"Suffering","source":"Dhammapada 5 (translation varies; excerpt)","reflection_prompt":"How might refusing retaliation alter a conflict?","review_status":"pending","is_published":false},{"legacy_id":76,"quote_text":"A frog in a well cannot be talked with about the sea.","author":"Zhuangzi","theme":"Doubt","source":"Zhuangzi, Autumn Floods (translation varies)","reflection_prompt":"Which limits of experience have you mistaken for limits of reality?","review_status":"pending","is_published":false},{"legacy_id":77,"quote_text":"Learning without thought is labor lost; thought without learning is perilous.","author":"Confucius","theme":"Action","source":"Analects 2.15 (James Legge translation, wording abridged)","reflection_prompt":"What balance between study and reflection works for you?","review_status":"pending","is_published":false},{"legacy_id":78,"quote_text":"To know what you know and what you do not know, that is true knowledge.","author":"Confucius","theme":"Doubt","source":"Analects 2.17 (translation varies)","reflection_prompt":"Where might admitting ignorance be a sign of understanding?","review_status":"pending","is_published":false},{"legacy_id":79,"quote_text":"One must still have chaos in oneself to be able to give birth to a dancing star.","author":"Friedrich Nietzsche","theme":"Beauty","source":"Thus Spoke Zarathustra, Prologue (translation varies)","reflection_prompt":"Can creativity emerge without uncertainty or disorder?","review_status":"pending","is_published":false},{"legacy_id":80,"quote_text":"Become who you are.","author":"Friedrich Nietzsche","theme":"Freedom","source":"The Gay Science, §270 (translation varies)","reflection_prompt":"Can you become yourself without discovering something new?","review_status":"pending","is_published":false},{"legacy_id":81,"quote_text":"God is dead. God remains dead. And we have killed him.","author":"Friedrich Nietzsche","theme":"Meaning","source":"The Gay Science, §125 (translation varies)","reflection_prompt":"What follows when inherited sources of meaning lose authority?","review_status":"pending","is_published":false},{"legacy_id":82,"quote_text":"I am myself the matter of my book.","author":"Michel de Montaigne","theme":"Meaning","source":"Essays, To the Reader (translation varies)","reflection_prompt":"What could you learn by making your experience a subject of inquiry?","review_status":"pending","is_published":false},{"legacy_id":83,"quote_text":"The path up and down is one and the same.","author":"Heraclitus","theme":"Time","source":"Fragment B60 (translation varies)","reflection_prompt":"How can opposite directions belong to the same process?","review_status":"pending","is_published":false},{"legacy_id":84,"quote_text":"Our heart is restless until it rests in you.","author":"Augustine of Hippo","theme":"Love","source":"Confessions I.1 (translation varies)","reflection_prompt":"What longing seems to persist beneath the things you pursue?","review_status":"pending","is_published":false},{"legacy_id":85,"quote_text":"Nothing can be created from nothing.","author":"Lucretius","theme":"Doubt","source":"On the Nature of Things, Book I (translation varies)","reflection_prompt":"What does an explanation need to account for?","review_status":"pending","is_published":false},{"legacy_id":86,"quote_text":"We are all in the gutter, but some of us are looking at the stars.","author":"Oscar Wilde","theme":"Beauty","source":"Lady Windermere's Fan, Act III","reflection_prompt":"What allows hope without denying difficult circumstances?","review_status":"pending","is_published":false},{"legacy_id":87,"quote_text":"The true mystery of the world is the visible, not the invisible.","author":"Oscar Wilde","theme":"Beauty","source":"The Picture of Dorian Gray, Chapter II","reflection_prompt":"What ordinary sight have you stopped seeing?","review_status":"pending","is_published":false},{"legacy_id":88,"quote_text":"One cannot think well, love well, sleep well, if one has not dined well.","author":"Virginia Woolf","theme":"Action","source":"A Room of One's Own, Chapter I","reflection_prompt":"How do material conditions shape the freedom to think?","review_status":"pending","is_published":false},{"legacy_id":89,"quote_text":"Nothing is so painful to the human mind as a great and sudden change.","author":"Mary Shelley","theme":"Suffering","source":"Frankenstein, Chapter XXIII (1818 edition varies)","reflection_prompt":"Which change have you needed time to understand?","review_status":"pending","is_published":false},{"legacy_id":90,"quote_text":"The feeling of commiseration is the beginning of humanity.","author":"Mencius","theme":"Love","source":"Mencius 2A:6 (translation varies)","reflection_prompt":"Where does empathy begin before deliberate reasoning?","review_status":"pending","is_published":false}]\n$quotes$::jsonb) AS q(legacy_id integer,quote_text text,author text,theme text,source text,reflection_prompt text,review_status text,is_published boolean))\nINSERT INTO public.quotes(legacy_id,quote_text,author,theme,source,reflection_prompt,review_status,is_published)\nSELECT legacy_id,quote_text,author,theme,source,reflection_prompt,review_status,is_published FROM entries ON CONFLICT (legacy_id) DO NOTHING;\n